.mobile-menu a[aria-current='page'] {
  color: color-mix(in srgb, var(--text) 80%, var(--accent-clay));
}

main {
  padding-block: clamp(2.4rem, 5vw, 5rem) clamp(4.5rem, 8vw, 7rem);
}

.eyebrow {
  font-size: 0.8rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.hero {
  padding-block: clamp(3.2rem, 10vw, 8rem) clamp(2.7rem, 7vw, 5.8rem);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  align-items: end;
  gap: clamp(2rem, 5vw, 4.2rem);
}

.display {
  font-family: 'Playfair Display', Georgia, serif;
  font-weight: 700;
  font-size: clamp(2.4rem, 7.5vw, 7rem);
  line-height: 0.95;
  letter-spacing: -0.02em;
}

.lead {
  max-width: 38ch;
  color: color-mix(in srgb, var(--text) 83%, var(--muted));
  font-size: clamp(1rem, 1.2vw, 1.15rem);
}

.section {
  padding-block: clamp(3.5rem, 9vw, 7rem);
  border-top: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
}

.section-grid {
  display: grid;
  grid-template-columns: 0.38fr 1fr;
  gap: clamp(1.6rem, 4vw, 4rem);
}

h2,
.h2 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2rem, 4.8vw, 4.4rem);
  line-height: 0.95;
  letter-spacing: -0.015em;
}

h3,
.h3 {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.35rem, 2.5vw, 2.2rem);
  line-height: 1.04;
  letter-spacing: -0.01em;
}

.text-block {
  max-width: 62ch;
  color: color-mix(in srgb, var(--text) 86%, var(--muted));
}

.services-list {
  display: grid;
  gap: clamp(1.2rem, 2.2vw, 2rem);
}

.service-item {
  padding-bottom: 1rem;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
}

.service-item p {
  margin-top: 0.55rem;
  color: color-mix(in srgb, var(--text) 84%, var(--muted));
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 1rem;
  min-height: 440px;
}

.media-block {
  border-radius: 2px;
  min-height: 160px;
}

.media-block.a {
  grid-column: 1 / 7;
  grid-row: 1 / 3;
  background: var(--accent-terracotta);
}

.media-block.b {
  grid-column: 7 / 10;
  grid-row: 1 / 2;
  background: var(--accent-sage);
}

.media-block.c {
  grid-column: 10 / 13;
  grid-row: 1 / 3;
  background: var(--accent-sand);
}

.media-block.d {
  grid-column: 1 / 4;
  grid-row: 3 / 4;
  background: var(--accent-clay);
}

.media-block.e {
  grid-column: 4 / 10;
  grid-row: 2 / 4;
  background: var(--accent-olive);
}

.marquee-wrap {
  overflow: hidden;
  border-top: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  padding-block: 1.1rem;
}

.marquee-row {
  display: flex;
  width: max-content;
  gap: 3.2rem;
  white-space: nowrap;
  will-change: transform;
  margin-block: 0.45rem;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.25rem, 2.2vw, 2.2rem);
}

.marquee-row span {
  color: color-mix(in srgb, var(--text) 88%, var(--muted));
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(1.2rem, 2.4vw, 2.2rem);
}

.client-card {
  padding-top: 0.75rem;
  border-top: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
}

.client-card h3 {
  font-size: clamp(1.18rem, 2vw, 1.7rem);
}

.client-card p {
  margin-top: 0.45rem;
  font-size: 0.95rem;
  color: color-mix(in srgb, var(--text) 82%, var(--muted));
}

.letter-layout {
  display: grid;
  grid-template-columns: 0.32fr 1fr;
  gap: clamp(2rem, 4vw, 4rem);
}

.letter-body {
  max-width: 68ch;
}

.letter-body p,
.letter-body ul {
  margin-bottom: 1.2rem;
  color: color-mix(in srgb, var(--text) 87%, var(--muted));
  font-size: clamp(1.02rem, 1.25vw, 1.16rem);
}

.letter-body ul {
  padding-left: 1.2rem;
}

.contact-hero {
  min-height: calc(100vh - 170px);
  display: grid;
  align-content: space-between;
  gap: 2rem;
}

.contact-display {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(4rem, 18vw, 15rem);
  line-height: 0.8;
  letter-spacing: -0.03em;
}

.contact-links {
  display: flex;
  gap: clamp(1.2rem, 3vw, 2.8rem);
  flex-wrap: wrap;
  padding-bottom: 1rem;
}

.contact-links a {
  font-size: clamp(1rem, 1.4vw, 1.22rem);
  border-bottom: 1px solid color-mix(in srgb, var(--text) 45%, transparent);
}

.site-footer {
  width: min(var(--max-width), 94vw);
  margin: 0 auto;
  padding: 1.35rem 0 1.8rem;
  border-top: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  color: color-mix(in srgb, var(--text) 70%, var(--muted));
  font-size: 0.82rem;
}

@media (max-width: 980px) {
  .desktop-nav {
    display: none;
  }

  .nav-toggle {
    display: inline-block;
  }

  .hero-grid,
  .section-grid,
  .letter-layout {
    grid-template-columns: 1fr;
  }

  .media-grid {
    grid-template-columns: repeat(2, 1fr);
    min-height: auto;
  }

  .media-block,
  .media-block.a,
  .media-block.b,
  .media-block.c,
  .media-block.d,
  .media-block.e {
    grid-column: auto;
    grid-row: auto;
    min-height: 150px;
  }

  .clients-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }

  .header-inner {
    min-height: 74px;
  }

  main {
    padding-top: 1.5rem;
  }
}
